import{_ as a,a0 as d,w as r,s,I as e,x as i,a1 as n,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"用 Linux blkid 命令查找塊設備詳情 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux blkid 命令查找塊設備詳情 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux blkid 命令查找塊設備詳情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux blkid 命令查找塊設備詳情 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141124 Linux blkid Command to Find Block Devices Details","title":"用 Linux blkid 命令查找塊設備詳情","tag":"201501","desc":""},"relativePath":"201501/20141124 Linux blkid Command to Find Block Devices Details.md","filePath":"[post].md"}'),b={name:"201501/20141124 Linux blkid Command to Find Block Devices Details.md"};function k(m,l,u,x,g,h){const t=d("Link");return r(),s("div",null,[l[17]||(l[17]=e("h1",{id:"用-linux-blkid-命令查找塊設備詳情",tabindex:"-1"},[i("用 Linux blkid 命令查找塊設備詳情 "),e("a",{class:"header-anchor",href:"#用-linux-blkid-命令查找塊設備詳情","aria-label":"Permalink to “用 Linux blkid 命令查找塊設備詳情”"},"​")],-1)),l[18]||(l[18]=e("p",null,[i("今天我們將會向你展示如何使用 "),e("strong",null,"lsblk"),i(" 和 "),e("strong",null,"blkid"),i(" 工具來查找關於塊設備的信息，我們使用的是一台安裝了 CentOS 7.0 的機器。")],-1)),l[19]||(l[19]=e("h2",{id:"lsblk",tabindex:"-1"},[i("lsblk "),e("a",{class:"header-anchor",href:"#lsblk","aria-label":"Permalink to “lsblk”"},"​")],-1)),e("p",null,[l[1]||(l[1]=e("strong",null,"lsblk",-1)),l[2]||(l[2]=i(" 是一個 Linux 工具，它會顯示有關你係統裏所有可用塊設備的信息。它從 ",-1)),n(t,{href:"https://www.kernel.org/doc/Documentation/filesystems/sysfs.txt"},{default:o(()=>[...l[0]||(l[0]=[i("sysfs 文件系統",-1)])]),_:1}),l[3]||(l[3]=i(" 中獲取信息。默認情況下，這個工具將會以樹狀格式顯示（除了內存虛擬磁盤外的）所有塊設備。",-1))]),l[20]||(l[20]=p(`<h3 id="lsblk-默認輸出" tabindex="-1">lsblk 默認輸出 <a class="header-anchor" href="#lsblk-默認輸出" aria-label="Permalink to “lsblk 默認輸出”">​</a></h3><p>默認情況下 lsblk 會將塊設備輸出為樹狀格式：</p><ul><li><p><strong>NAME</strong> —— 設備的名稱</p></li><li><p><strong>MAJ:MIN</strong> —— Linux 操作系統中的每個設備都以一個文件表示，對塊（磁盤）設備來説，這裏用主次設備編號來描述設備。</p></li><li><p><strong>RM</strong> —— 可移動設備。如果這是一個可移動設備將顯示 1，否則顯示 0。</p></li><li><p><strong>TYPE</strong> —— 設備的類型</p></li><li><p><strong>MOUNTPOINT</strong> —— 設備掛載的位置</p></li><li><p><strong>RO</strong> —— 對於只讀文件系統，這裏會顯示 1，否則顯示 0。</p></li><li><p><strong>SIZE</strong> —— 設備的容量</p></li></ul><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/lsblk.jpg" alt=""></p><h3 id="顯示設備的所有者" tabindex="-1">顯示設備的所有者 <a class="header-anchor" href="#顯示設備的所有者" aria-label="Permalink to “顯示設備的所有者”">​</a></h3><p>若想顯示設備所有者相關的信息，包括文件的所屬用户、所屬組以及文件系統掛載的模式，你可以使用 -m 選項，像這樣：</p><pre><code>lsblk -m
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/lsblk-m.jpg" alt=""></p><h3 id="列出設備塊" tabindex="-1">列出設備塊 <a class="header-anchor" href="#列出設備塊" aria-label="Permalink to “列出設備塊”">​</a></h3><p>如果你只想要列出設備，而不想讓他們以樹狀輸出，你可以使用 -l 選項：</p><pre><code>lsblk -l
</code></pre><h3 id="在腳本中使用" tabindex="-1">在腳本中使用 <a class="header-anchor" href="#在腳本中使用" aria-label="Permalink to “在腳本中使用”">​</a></h3><p>高級技巧：如果你想要在腳本中使用而希望剔除表頭，你可以這樣使用 -n 選項：</p><pre><code>lsblk -ln
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/lsblk-ln.jpg" alt=""></p><h2 id="blkid" tabindex="-1">blkid <a class="header-anchor" href="#blkid" aria-label="Permalink to “blkid”">​</a></h2><p><strong>blkid</strong> 命令是一個命令列工具，它可以顯示關於可用塊設備的信息。它可以識別一個塊設備內容的類型（如文件系統、交換區）以及從內容的元數據（如卷標或 UUID 字段）中獲取屬性（如 tokens 和鍵值對）。它主要有兩類作用：用指定的鍵值對搜索一個設備，或是顯示一個或多個設備的鍵值對。</p><h3 id="blkid-使用方法" tabindex="-1">blkid 使用方法 <a class="header-anchor" href="#blkid-使用方法" aria-label="Permalink to “blkid 使用方法”">​</a></h3><p>不添加任何參數直接運行 blkid 將會輸出所有可用的設備、它們的通用唯一識別碼（UUID）、文件系統類型以及卷標（如果有設置過）。</p><pre><code># blkid
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/blkid.jpg" alt=""></p><h3 id="根據名字或-uuid-列出設備" tabindex="-1">根據名字或 UUID 列出設備 <a class="header-anchor" href="#根據名字或-uuid-列出設備" aria-label="Permalink to “根據名字或 UUID 列出設備”">​</a></h3><p>如果你只想顯示一個特定設備的信息，你可以將該設備的名字作為選項添加在 blkid 後面：</p><pre><code># blkid /dev/sda1
</code></pre><p>如果你知道一個設備的 UUID 而想要知道它的設備名，你可以用 -U 選項，像這樣：</p><pre><code># blkid -U d3b1dcc2-e3b0-45b0-b703-d6d0d360e524
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/blkid-uuid.jpg" alt=""></p><h3 id="詳細信息" tabindex="-1">詳細信息 <a class="header-anchor" href="#詳細信息" aria-label="Permalink to “詳細信息”">​</a></h3><p>如果你想要獲取更多詳細信息，你可以使用 -p 和 -o udev 選項來將它們用整齊的格式顯示出來，像這樣：</p><pre><code># blkid -po udev /dev/sda1
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/blkid-po.jpg" alt=""></p><h3 id="重置緩存" tabindex="-1">重置緩存 <a class="header-anchor" href="#重置緩存" aria-label="Permalink to “重置緩存”">​</a></h3><p>有時候設備列表可能不會更新，如果遇到這種情況你可以使用 -g 選項來清理 blkid 的緩存，從而清除已經不存在的設備。</p><pre><code># blkid -g
</code></pre><hr>`,35)),e("p",null,[l[5]||(l[5]=i("via: ",-1)),n(t,{href:"http://linoxide.com/linux-command/linux-command-lsblk-blkid/"},{default:o(()=>[...l[4]||(l[4]=[i("http://linoxide.com/linux-command/linux-command-lsblk-blkid/",-1)])]),_:1})]),e("p",null,[l[9]||(l[9]=i("作者：",-1)),n(t,{href:"http://linoxide.com/author/adriand/"},{default:o(()=>[...l[6]||(l[6]=[i("Adrian Dinu",-1)])]),_:1}),l[10]||(l[10]=i(" 譯者：",-1)),n(t,{href:"https://github.com/felixonmars"},{default:o(()=>[...l[7]||(l[7]=[i("felixonmars",-1)])]),_:1}),l[11]||(l[11]=i(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...l[8]||(l[8]=[i("wxy",-1)])]),_:1})]),e("p",null,[l[14]||(l[14]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[12]||(l[12]=[i("LCTT",-1)])]),_:1}),l[15]||(l[15]=i(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...l[13]||(l[13]=[i("Linux中國",-1)])]),_:1}),l[16]||(l[16]=i(" 榮譽推出",-1))])])}const c=a(b,[["render",k]]);export{L as __pageData,c as default};
